"""Camera-guided bowl alignment. Live commands and trajectories are recorded beside this file.
Run --interactive for the same client-driven workflow, or run without flags to replay commands.
Only standard RGB/depth, proprioception and public FK/IK are used.
"""
import sys, json, pathlib, time
sys.path.insert(0, '/opt/tools')
import numpy as np
from rcb_client import Robot, EpisodeOver

OUT=pathlib.Path('/app/output'); OUT.mkdir(exist_ok=True)
JOURNAL=OUT/'commands.jsonl'

class Controller:
    def __init__(self):
        self.r=Robot(); self.spec=self.r.spec(); self.i=0
        (OUT/'spec.json').write_text(json.dumps(self.spec,indent=2))
        self.obs=self.r.get_obs(depth=True); self.save(self.obs,'connected')
    def save(self,res,note):
        self.obs=res; self.i+=1
        path=f'/app/runs/{self.i:03d}_{note}'
        res.save(path)
        (OUT/'latest_meta.json').write_text(json.dumps(res.meta,indent=2))
        (OUT/'latest_path.txt').write_text(path)
        print(json.dumps({'path':path,'done':res.meta.get('done'),'reason':res.meta.get('reason'),
                          'time_left_s':res.meta.get('time_left_s'),'control_steps':res.meta.get('control_steps'),
                          'now':res.meta['proprio']['now'],'plan':res.meta.get('plan'),'stopped':res.stopped}),flush=True)
    def call(self,c,record=True):
        op=c['op']
        if op=='status': print(json.dumps(self.r.status()),flush=True);return
        if op=='observe':
            res=self.r.get_obs(seconds=c.get('seconds',0),depth=True,video='none');self.save(res,c.get('note','observe'));return
        now=np.array(self.obs.meta['proprio']['now']); q14=np.r_[now[:7],now[8:15]]
        if op=='ik':
            ans=self.r.ik(c['targets'],seed=c.get('seed',q14.tolist()),max_iters=c.get('max_iters',300))
            print(json.dumps(ans),flush=True);(OUT/'last_ik.json').write_text(json.dumps(ans));return
        if op=='fk':
            print(json.dumps(self.r.fk(c.get('q',q14.tolist()),links=c.get('links'))),flush=True);return
        if op=='move':
            ans=self.r.ik(c['targets'],seed=q14,max_iters=300)
            print(json.dumps({'ik':ans}),flush=True)
            if not ans['ok']: return
            goal=now[:16].copy();q=np.array(ans['q']);goal[:7]=q[:7];goal[8:15]=q[7:]
            for k,j in [('right_gripper',7),('left_gripper',15)]:
                if k in c:goal[j]=c[k]
            duration=c.get('duration',3);n=max(2,int(round(duration/.1)))
            a=np.linspace(now[:16],goal,n+1)
            c={'op':'submit','type':'joint_position','actions':a.tolist(),'dt':.1,'note':c.get('note','move')}
        if op=='grip':
            goal=now[:16].copy();goal[7 if c['arm']=='right' else 15]=c['width']
            a=np.linspace(now[:16],goal,11)
            c={'op':'submit','type':'joint_position','actions':a.tolist(),'dt':.1,'note':c.get('note','grip')}
        if c['op']=='submit':
            if record:
                with JOURNAL.open('a') as f:f.write(json.dumps(c)+'\n')
            try:
                res=self.r.submit(c['type'],c['actions'],dt=c.get('dt',.1),video='none',depth=True,note=c.get('note',''))
            except Exception:
                print('Service error: waiting for the same episode to resume.',flush=True)
                self.r.wait_ready();print(json.dumps(self.r.status()),flush=True)
                self.save(self.r.get_obs(depth=True),'recovered');return
            self.save(res,c.get('note','submit'))
        if self.obs.meta.get('done'):
            (OUT/'final_status.json').write_text(json.dumps(self.r.status(),indent=2))

if __name__=='__main__':
    ctrl=Controller()
    if '--interactive' in sys.argv:
        for line in sys.stdin:
            try:ctrl.call(json.loads(line))
            except EpisodeOver as e:print(json.dumps({'episode_over':str(e)}),flush=True)
            except Exception as e:print(json.dumps({'error':str(e)}),flush=True)
    else:
        commands=[json.loads(s) for s in JOURNAL.read_text().splitlines()]
        for c in commands:
            if ctrl.obs.meta.get('done'):break
            ctrl.call(c,record=False)
PY
